function actPlot(i){if(paused)return notify('先继续游戏，让月球重新转起来。');let p=state.plots[i];bunnyTarget.set(plotGroups[i].position.x+.8,0,plotGroups[i].position.z+.8);walking=true;if(tool==='inspect'){activePlot=i;openPanel('plot');return}if(p?.growth>=1){state.bag[p.crop]+=state.upgrades.includes('yield')?2:1;state.stats.harvest++;gainXP(8);state.plots[i]=null;buildPlant(i);burst(plotGroups[i].position);notify(`${crops[p.crop].icon} 收获 ${crops[p.crop].name}！放入背包，可出售换取月光币。`);chime(740)}else if(tool==='plant'){if(p)return notify('这位小家伙正在长大，试试给它浇水吧。');if(state.seeds[seed]<=0)return notify('这袋种子用完啦，到种子商店补充一些吧。');state.seeds[seed]--;state.plots[i]={crop:seed,growth:0,wet:0};state.stats.plant++;gainXP(2);buildPlant(i);burst(plotGroups[i].position,0xb1d7a4);notify('♧ 种下 '+crops[seed].name+' · 浇一点月露会长得更快');chime(450)}else if(tool==='water'){if(!p)return notify('先种一颗种子，再给它浇水吧。');if(p.wet>15)return notify('月壤还很湿润，不需要重复浇水哦。');if(state.water<1)return notify('月露不足，商店可补给，每个新月球日也会补充。');state.water--;p.wet=45;state.stats.water++;gainXP(1);burst(plotGroups[i].position,0xa9dce7);notify('◈ 浇水完成 · 45 秒双倍生长');chime(570)}else notify('还没有成熟哦，让星光再照一会儿。');updateHUD();save()}
function setTool(t){tool=t;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#action-hint').textContent={plant:'点击空地种植 · 成熟作物点击即可收获',water:'点击作物浇水 · 湿润月壤生长速度 ×2',harvest:'点击成熟作物收获 · 去背包出售换月光币',inspect:'点击地块查看作物状态和生长详情'}[t]}
$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$$('[data-panel]').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));$('#seed-button').onclick=()=>openPanel('seeds');$('#help').onclick=()=>openPanel('help');$('#journal').onclick=()=>openPanel('journal');$('#close-modal').onclick=closeModal;$('#modal-overlay').onclick=e=>{if(e.target===$('#modal-overlay'))closeModal()};let focusBefore;function closeModal(){$('#modal-overlay').classList.add('hidden');modalType='';focusBefore?.focus()}
function title(en,name,sub){return `<div class="modal-eyebrow">${en}</div><h2 id="modal-title">${name}</h2><p class="sub">${sub}</p>`}
const upgrades=[{id:'water',icon:'◈',name:'月露收集器',desc:'每 25 秒收集 1 滴月露，让浇灌更轻松。',cost:160,crystals:1},{id:'growth',icon:'⚗',name:'星尘营养液',desc:'所有作物永久生长加速 35%。',cost:240,crystals:2},{id:'land',icon:'▦',name:'拓展小小花园',desc:'开垦南侧月壤，种植地块从 12 块扩展至 16 块。',cost:280,crystals:2},{id:'yield',icon:'✿',name:'双生基因研究',desc:'每次收获获得 2 份作物。两份快乐，一起生长。',cost:420,crystals:4}];
function openPanel(type){if($('#modal-overlay').classList.contains('hidden'))focusBefore=document.activeElement;modalType=type;let h='';if(type==='shop'){h=title('THE COSMIC SEED CO.','星际种子商店','每一颗种子，都藏着一个小宇宙。种植与收获可提升园丁等级。')+`<div class="status-strip">✦ ${state.coins} 月光币　 /　 ◈ ${Math.floor(state.water)} 月露</div><div class="grid">`+crops.map((c,i)=>`<article class="item"><span class="item-icon">${c.icon}</span><h3>${c.name}</h3><p>基础生长 ${c.time} 秒 · 售价 ${c.sell}<br>种子库存 ${state.seeds[i]} · Lv.${c.level} 解锁</p><button data-buy="${i}" ${level()<c.level||state.coins<c.cost?'disabled':''}>${level()<c.level?'需要 Lv.'+c.level:'✦ '+c.cost+' / 购买种子'}</button></article>`).join('')+`<article class="item"><span class="item-icon">💧</span><h3>一瓶月露</h3><p>补充 10 滴月露，滋养你的花园。</p><button id="buy-water" ${state.coins<25?'disabled':''}>✦ 25 / 补充 10 月露</button></article></div>`}else if(type==='seeds'){h=title('A LITTLE BEGINNING','今天想种什么？','选择一袋种子，再点击空地。你也可以用键盘 1–4 切换农具。')+'<div class="grid">'+crops.map((c,i)=>`<article class="item ${seed===i?'owned':''}"><span class="item-icon">${c.icon}</span><h3>${c.name}</h3><p>库存 ${state.seeds[i]} 颗 · 基础生长 ${c.time} 秒</p><button data-seed="${i}" ${state.seeds[i]===0?'disabled':''}>${seed===i?'当前选择':'选择种植'}</button></article>`).join('')+'</div>'}else if(type==='bag'){h=title('LITTLE THINGS, BIG JOY','阿月的背包','把收获卖给路过的星际商人，再为花园添一点新东西。')+`<div class="status-strip">✧ 月晶石 ${state.crystals} 枚　 /　累计收获 ${state.stats.harvest} 次</div>`+crops.map((c,i)=>`<div class="inventory-row"><span class="emoji">${c.icon}</span><div><strong>${c.name} × ${state.bag[i]}</strong><small>种子 ${state.seeds[i]} 颗 · 出售价 ${c.sell} 月光币</small></div><button data-sell="${i}" ${state.bag[i]===0?'disabled':''}>出售全部 +${state.bag[i]*c.sell}</button></div>`).join('')}else if(type==='lab'){h=title('MADE OF MOONDUST','月球小工坊','用月光币和探索得到的月晶石，为小小基地发明大大的可能。')+`<div class="status-strip">✦ ${state.coins} 月光币　 /　 ✧ ${state.crystals} 月晶石</div><div class="grid">`+upgrades.map(u=>`<article class="item ${state.upgrades.includes(u.id)?'owned':''}"><span class="item-icon">${u.icon}</span><h3>${u.name}</h3><p>${u.desc}</p><span class="meta">✦ ${u.cost} 月光币 + ${u.crystals} 月晶石</span><button data-upgrade="${u.id}" ${state.upgrades.includes(u.id)||state.coins<u.cost||state.crystals<u.crystals?'disabled':''}>${state.upgrades.includes(u.id)?'✓ 已建造':'开始建造'}</button></article>`).join('')+'</div>'}else if(type==='explore'){h=title('A SMALL STEP INTO THE UNKNOWN','去星野散个步','每次探索消耗能量，并带回月晶石、种子或月光币。能量随时间恢复。')+`<div class="status-strip">ϟ 当前能量 ${Math.floor(state.energy)} / 100　 ·　已发现 ${state.discoveries.length} / 6 种月球奇遇</div><div class="grid">`+[{name:'静海陨石坑',icon:'☾',cost:20,text:'温柔的环形山里，藏着月晶石与迷路的种子。'},{name:'星尘水晶洞',icon:'✧',cost:35,text:'更加遥远的闪光洞穴。保底两枚月晶石，额外收获更多。'}].map((e,i)=>`<article class="item"><span class="item-icon">${e.icon}</span><h3>${e.name}</h3><p>${e.text}</p><button data-explore="${i}" ${state.energy<e.cost?'disabled':''}>ϟ ${e.cost} / 出发探索</button></article>`).join('')+'</div><p class="sub">旅行日志记录在星际手账中。慢慢走，总会遇见惊喜。</p>'}else if(type==='journal'){h=title('LET THE LITTLE THINGS GROW','星际手账',`你在月球的第 ${state.day} 天。已种植 ${state.stats.plant} 次，收获 ${state.stats.harvest} 次，探索 ${state.stats.explore} 次。`)+quests.map(q=>`<div class="inventory-row"><span class="emoji">${q.icon}</span><div><strong>${q.title}</strong><small>${Math.min(state.stats[q.id],q.target)} / ${q.target} · 奖励 ${q.reward} 月光币</small></div><button data-claim="${q.id}" ${state.claimed.includes(q.id)||state.stats[q.id]<q.target?'disabled':''}>${state.claimed.includes(q.id)?'✓ 已完成':'领取奖励'}</button></div>`).join('')+'<h3>月球奇遇图鉴</h3>'+ (state.discoveries.length?state.discoveries.map(d=>`<div class="inventory-row"><span class="emoji">✧</span><div><strong>${discoveries[d][0]}</strong><small>${discoveries[d][1]}</small></div></div>`).join(''):'<p class="sub">还没有旅行故事，去星野探索一次吧。</p>')}else if(type==='plot'){let p=state.plots[activePlot];h=title('GARDEN OBSERVATORY',p?crops[p.crop].icon+' '+crops[p.crop].name:'一片充满可能的月壤',p?'从一粒种子，到一份属于自己的收获。':'选择喜欢的种子，给月球添一点颜色。');if(p){h+=`<div class="status-strip">生长进度 ${Math.floor(p.growth*100)}%　 /　${p.growth>=1?'已成熟':p.wet>0?'湿润 · 加速生长':'干燥 · 普通生长'}</div><p class="sub">基础生长时间 ${crops[p.crop].time} 秒（湿润时速度翻倍）。<br>单份作物售价 ${crops[p.crop].sell} 月光币。</p><button class="primary" id="plot-act">${p.growth>=1?'收获这份星光':'给作物浇水'}</button>`}else h+='<button class="primary" id="plot-act">种下一颗 '+crops[seed].name+'</button>'}else{h=title('WELCOME TO YOUR LITTLE MOON','欢迎回家，星尘园丁。','这里没有催促你的时钟。让小兔阿月陪你，种出自己的宇宙田园。')+`<div class="help-grid"><span>♧</span><p><b>种下一个开始</b><br>选择种子，点击空地种植。用 1–4 切换种植、浇水、收获和观察。</p><span>◈</span><p><b>照顾你的小宇宙</b><br>浇水让生长速度翻倍，成熟后点击即可收获。背包里出售作物，商店里买新种子。</p><span>✧</span><p><b>去发现更多可能</b><br>探索获得月晶石，在工坊升级设施。积累经验解锁 6 种外星作物，完成任务领取奖励。</p><span>☾</span><p><b>按自己的节奏生活</b><br>每 4 分钟迎来新月球日，补充 8 滴月露并变换天气。拖拽旋转、滚轮缩放，点击地面让小兔散步。</p><span>♡</span><p><b>进度在这台设备上保存</b><br>游戏每几秒自动存档；关闭页面后作物暂停生长。右上角可暂停或开启音乐。</p></div>`}$('#modal-content').innerHTML=h;$('#modal-overlay').classList.remove('hidden');$('#close-modal').focus();wirePanel()}
const discoveries=[['会唱歌的石头','轻轻敲一敲，就会响起遥远星球的旋律。'],['睡着的星鲸','在环形山里打盹，它梦见了一整片海。'],['旧时光邮筒','里面有一封写给未来园丁的信：要记得开心。'],['银河蝴蝶','翅膀上是没有见过的星座。'],['月兔的脚印','原来宇宙里，不止你喜欢种萝卜。'],['发光的雨','没有云的地方，也会下起温柔的雨。']];
function wirePanel(){$$('[data-buy]').forEach(b=>b.onclick=()=>{let i=+b.dataset.buy,c=crops[i];if(level()<c.level||state.coins<c.cost)return;state.coins-=c.cost;state.seeds[i]++;notify(c.icon+' 收到一颗 '+c.name+' 种子');chime(520);finish('shop')});$('#buy-water')?.addEventListener('click',()=>{if(state.coins<25)return;state.coins-=25;state.water+=10;finish('shop');notify('◈ 月露 +10，花园又有水喝了。')});$$('[data-seed]').forEach(b=>b.onclick=()=>{seed=+b.dataset.seed;setTool('plant');updateHUD();closeModal();notify('♧ 选择了 '+crops[seed].name+'，点击空地开始种植')});$$('[data-sell]').forEach(b=>b.onclick=()=>{let i=+b.dataset.sell,n=state.bag[i];if(!n)return;state.coins+=n*crops[i].sell;state.stats.sell+=n;state.bag[i]=0;notify('✦ 星际交易完成，获得 '+n*crops[i].sell+' 月光币');chime(880);finish('bag')});$$('[data-upgrade]').forEach(b=>b.onclick=()=>{let u=upgrades.find(u=>u.id===b.dataset.upgrade);if(state.coins<u.cost||state.crystals<u.crystals||state.upgrades.includes(u.id))return;state.coins-=u.cost;state.crystals-=u.crystals;state.upgrades.push(u.id);gainXP(20);if(u.id==='land')state.plots.forEach((p,i)=>buildPlant(i));notify('✧ '+u.name+' 建造完成！');burst(new THREE.Vector3(0,0,0));finish('lab')});$$('[data-explore]').forEach(b=>b.onclick=()=>{let deep=+b.dataset.explore,cost=deep?35:20;if(state.energy<cost)return;state.energy-=cost;state.stats.explore++;let crystal=deep?2+Math.floor(Math.random()*2):1;state.crystals+=crystal;let money=15+Math.floor(Math.random()*25)*(deep+1);state.coins+=money;let choices=crops.map((c,i)=>c.level<=level()?i:-1).filter(i=>i>=0),s=choices[Math.floor(Math.random()*choices.length)];state.seeds[s]++;let d=Math.floor(Math.random()*discoveries.length);if(!state.discoveries.includes(d))state.discoveries.push(d);gainXP(deep?15:9);bunnyTarget.set(-4,0,-3);walking=true;finish('explore');notify(`✧ 遇见${discoveries[d][0]}！月晶石 +${crystal}，月光币 +${money}，${crops[s].name}种子 +1`);chime(1000)});$$('[data-claim]').forEach(b=>b.onclick=()=>claim(b.dataset.claim));$('#plot-act')?.addEventListener('click',()=>{let p=state.plots[activePlot];setTool(p?p.growth>=1?'harvest':'water':'plant');closeModal();actPlot(activePlot)})}
function finish(panel){updateHUD();save();if(panel)openPanel(panel)}
$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'继续游戏':'暂停');$('#pause').title=paused?'继续游戏':'暂停';if(paused){let d=document.createElement('div');d.className='pause-banner';d.id='pause-banner';d.textContent='☾ 让宇宙歇一会儿';document.body.append(d)}else $('#pause-banner')?.remove()};$('#rotate').onclick=()=>angle+=Math.PI/4;$('#zoom-in').onclick=()=>zoom=Math.max(15,zoom-2);$('#zoom-out').onclick=()=>zoom=Math.min(34,zoom+2);$('#sound').onclick=()=>{muted=!muted;$('#sound').style.background=muted?'#ffffff0c':'#8370aa';$('#sound').title=muted?'开启环境音乐':'关闭环境音乐';$('#sound').setAttribute('aria-label',$('#sound').title);if(!muted){audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();[130.81,196,261.63,329.63].forEach((f,i)=>{let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;g.gain.value=.006;o.connect(g).connect(audioCtx.destination);o.start();ambience.push(o)});chime()}else{ambience.forEach(o=>o.stop());ambience=[]}};
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return}if(modalType){if(e.key==='Tab'){let items=$$('#modal button:not(:disabled)');let first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}let n=Number(e.key);if(n>=1&&n<=4)setTool(['plant','water','harvest','inspect'][n-1]);if(e.code==='Space'){e.preventDefault();$('#pause').click()}if(e.key.toLowerCase()==='b')openPanel('bag');if(e.key.toLowerCase()==='q')angle-=.2;if(e.key.toLowerCase()==='e')angle+=.2});
let prev=performance.now(),acc=0,saveAcc=0,waterAcc=0,t=0;function step(dt){state.seconds+=dt;state.totalTime+=dt;state.energy=Math.min(100,state.energy+dt*.6);if(state.seconds>=240){state.seconds-=240;state.day++;state.water+=8;state.weather=Math.floor(Math.random()*3);notify(`☾ 月球日 ${state.day} · 月露 +8，今天也请多关照。`)}if(state.upgrades.includes('water')){waterAcc+=dt;if(waterAcc>=25){waterAcc-=25;state.water++}}state.plots.forEach((p,i)=>{if(!p||p.growth>=1)return;if(state.weather===2)p.wet=8;let before=p.growth;p.growth=Math.min(1,p.growth+dt/crops[p.crop].time*(p.wet>0?2:1)*(state.weather===1?1.35:1)*(state.upgrades.includes('growth')?1.35:1));p.wet=Math.max(0,p.wet-dt);plantGroups[i].scale.setScalar(.2+.8*p.growth);plotMeshes[i].material=mat(p.wet>0?0x655569:0x776878);if(before<1&&p.growth>=1)burst(plotGroups[i].position)});acc+=dt;saveAcc+=dt;if(acc>.6){updateHUD();acc=0}if(saveAcc>4){save();saveAcc=0}}
function animate(now){requestAnimationFrame(animate);let dt=Math.min((now-prev)/1000,.05);prev=now;if(!paused&&!document.hidden){step(dt);t+=dt;if(walking){let d=bunnyTarget.clone().sub(bunny.position);d.y=0;if(d.length()<.1){walking=false;bunny.position.y=0}else{bunny.position.add(d.normalize().multiplyScalar(Math.min(dt*2.5,d.length())));bunny.position.y=Math.abs(Math.sin(t*10))*.2;bunny.rotation.y=Math.atan2(d.x,d.z)}}else{bunny.position.y=Math.sin(t*2)*.018}plantGroups.forEach((g,i)=>{if(state.plots[i])g.rotation.z=Math.sin(t*1.6+i)*.025});for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.m.position.addScaledVector(p.v,dt);p.v.y-=dt*1.5;p.m.scale.setScalar(Math.max(0,p.life));if(p.life<=0){scene.remove(p.m);p.m.geometry.dispose();particles.splice(i,1)}}}let effectiveZoom=zoom*(innerWidth<760?1.29:1);camera.position.set(Math.sin(angle)*effectiveZoom,effectiveZoom*.69,Math.cos(angle)*effectiveZoom);camera.lookAt(target);renderer.render(scene,camera)}window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});window.addEventListener('pagehide',save);updateHUD();requestAnimationFrame(animate);$('#loading').classList.add('hidden');setTimeout(()=>notify('☾ 欢迎回家！三株月光作物已经成熟，点击收获吧。'),800);
// Optional agent interface, sharing exactly the same actions as the visible farm.
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_moon_farm',description:'Read current farm resources, crop plots and inventory.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({day:state.day,coins:state.coins,water:state.water,energy:Math.floor(state.energy),level:level(),plots:state.plots,seeds:state.seeds,harvested:state.bag})});document.modelContext.registerTool({name:'tend_moon_plot',description:'Plant, water, inspect or harvest a specified unlocked farm plot using the same interface action.',inputSchema:{type:'object',properties:{plot:{type:'integer',minimum:0,maximum:15},action:{type:'string',enum:['plant','water','harvest','inspect']}},required:['plot','action'],additionalProperties:false},execute:({plot,action})=>{if(!Number.isInteger(plot)||plot<0||plot>=unlocked()||!['plant','water','harvest','inspect'].includes(action))throw Error('Invalid plot or action');setTool(action);actPlot(plot);return{plot:state.plots[plot],message:$('#toast').textContent}}})}catch(e){console.warn('Optional farm tools unavailable',e)}}
